#!/usr/bin/env node
/* MVP Trainer V5 R8.3 - Control Language Reset installer */
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";

const root = process.cwd();
const target = path.join(root, "src", "features", "music", "MusicMiniPlayer.tsx");
const expectedR82Sha256 = "baa75a11b6824179e4ba0c06197310e41dd0513895b748a745dc2f0d46c74ba5";
const expectedReplacementSha256 = "85e18766a19ee6befc40d59a8972cd136db530929dadb8425a010b376b67940b";
const replacementBase64 = "";
const sha256 = (buffer) => crypto.createHash("sha256").update(buffer).digest("hex");
function fail(message) { console.error(`\nR8.3 STOPPED: ${message}\n`); process.exit(1); }
if (!fs.existsSync(target)) fail(`Could not find ${path.relative(root,target)}. Run this from the MVP Trainer repo root.`);
const current = fs.readFileSync(target);
const currentText = current.toString("utf8");
const currentSha = sha256(current);
if (currentText.includes("MVP_TRAINER_V5_R8_3_CONTROL_LANGUAGE_RESET")) {
  console.log("\nMVP Trainer V5 R8.3 is already applied. No files changed.\n"); process.exit(0);
}
if (!currentText.includes("export function MusicMiniPlayer")) fail("The target file does not look like the MVP MusicMiniPlayer. Nothing was changed.");
if (currentSha !== expectedR82Sha256) fail("MusicMiniPlayer.tsx does not exactly match the R8.2 baseline this update was built against. Nothing was overwritten. Send the current MusicMiniPlayer.tsx if it has changed since R8.2.");
const replacement = Buffer.from(replacementBase64,"base64");
if (sha256(replacement) !== expectedReplacementSha256) fail("Replacement integrity check failed. Nothing was changed.");
const stamp = new Date().toISOString().replace(/[:.]/g,"-");
const backup = `${target}.bak-r8-3-${stamp}`;
fs.copyFileSync(target, backup);
fs.writeFileSync(target, replacement);
console.log("\nMVP Trainer V5 R8.3 applied successfully.");
console.log(`Updated: ${path.relative(root,target)}`);
console.log(`Backup:  ${path.relative(root,backup)}`);
console.log(`SHA-256: ${expectedReplacementSha256}`);
console.log("\nR8.3 resets the player control language, enlarges icon-first transport, converts Repeat/Shuffle to floating controls, unifies the Neural squares, shortens LIKE THIS/MELODIC labels, compacts hero actions, and repairs Playing From duplicate text.");
console.log("Next: run npm run build, then test desktop + mobile before committing.\n");
